import unittest
from candidate import total_match

class TestTotalMatch(unittest.TestCase):
    def test_empty_both_lists_returns_empty(self):
        self.assertEqual(total_match([], []), [])

    def test_example_hi_admin_vs_hI_Hi_returns_second(self):
        self.assertEqual(total_match(['hi', 'admin'], ['hI', 'Hi']), ['hI', 'Hi'])

    def test_example_hi_admin_vs_longer_list_returns_first(self):
        self.assertEqual(total_match(['hi', 'admin'], ['hi', 'hi', 'admin', 'project']), ['hi', 'admin'])

    def test_example_hi_admin_vs_hI_hi_hi_returns_second(self):
        self.assertEqual(total_match(['hi', 'admin'], ['hI', 'hi', 'hi']), ['hI', 'hi', 'hi'])

    def test_example_single_digit_vs_multi_return_first(self):
        self.assertEqual(total_match(['4'], ['1', '2', '3', '4', '5']), ['4'])

    def test_empty_first_list_nonempty_second_returns_first(self):
        self.assertEqual(total_match([], ['a']), [])

    def test_nonempty_first_list_empty_second_returns_second(self):
        self.assertEqual(total_match(['a'], []), [])

    def test_equal_char_counts_returns_first_list(self):
        self.assertEqual(total_match(['a'], ['a']), ['a'])

    def test_equal_char_counts_different_strings_returns_first(self):
        self.assertEqual(total_match(['hi'], ['H', 'i']), ['hi'])

    def test_empty_strings_returns_first_list(self):
        self.assertEqual(total_match([''], ['']), [''])

    def test_none_value_raises_type_error(self):
        with self.assertRaises(TypeError):
            total_match(None, ['a'])

    def test_non_list_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            total_match("abc", ["a"])
